) AS (
  VALUES 
    (63::BIGINT, 'El curso como tal es regalado, practicamente no se hacen examenes y hace las clases muy diferentes a un profesor "normal" pero sin duda son entretenidas, solo que se tiene que preparar para el proyecto final porque es el proyecto más pesado de toda la carrera si usted de verdad quiere hacer algobien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-09T00:00:00+00:00'::TIMESTAMPTZ, 'f9faf37513691bae03061c6dfedd356d420a682c1a6c2d7c69217e126f291812'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Es regalado el curso. Hace quices semanales (de 10 preguntas, ChatGPT te lo hace si no leiste aunque el libro es chiva) y si pasás todos te exime del examen. Hace giras y clases en el aire libre. Lo único que quita tiempo es que tenés que inventarte un producto para vender, pero lo demás es bello.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'bb5f8902991a59b672bf45f038de40c1f36a85d624072e12a56eebcf0281ada7'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Disfruté el curso, el proyecto final fue interesante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'f7175648c1e47f1c67530afb0b12300b9a1a34177673123ce96d06e88b91a498'::TEXT, ARRAY[2453]::BIGINT[]),
    (63::BIGINT, 'Es buena gente, las clases son fáciles, y si haces los socratives bien te exime de TODOS los examenes. Lo que sí es que el proyecto es desarrollar y vender un producto, y la meta de vendas y los retos son complicados. Con todo se pasa bien y no es tan dificil.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2024-12-10T00:00:00+00:00'::TIMESTAMPTZ, '2bf67e20ae2465076483ebcbe2a797fa63879c11e84ef9811c83eb5232e752f0'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ba784cd8a2f7a15d3c9164de55859659632a64eb5e76fb791155b785e4184834'::TEXT, ARRAY[1973, 1784, 1893, 1974, 1783]::BIGINT[]),
    (63::BIGINT, 'Buen profesor pero, hace las clases muy largas y los trabajos que deja aveces se pone muy creativo lo que lo hace algo complicado de realizar, además que si presenta problemas con su grupo de trabajo no lo va a ayudar a que los demás trabajen.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-09-20T00:00:00+00:00'::TIMESTAMPTZ, 'c5b63b7cfb7cf65dabcc67170b3035a0b66087c5c85ac0404330ced266c4a884'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'El proyecto demanda mucho tiempo y las instrucciones no son claras.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8679eb0a61bc975ed3c537dc84cdd0ee0d233ff9d064d4a967bcfec084fd65b2'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Es un buen profesor, sabe demasiado, sin embargo, hace las clases muy largas y los trabajos que deja aveces se pone muy creativo lo que lo hace algo complicado de realizar'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'effd0aeb709c4438a88ddff65ca757cb20f8347dcda814ddbe0afeca0385e8df'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Hace el curso muy pesado. Deja muchísimos trabajos y largos. Además, tiene muy poca empatía con los estudiantes cuando tienen dificultades.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'd00a19f1ea6765136888c472b281d2550a0f58b840cd424baec27512e7293253'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'El curso es muy interesante, exime del examen si tiene buenas notas en los quices semanales. El proyecto final si es bastante largo y demanda mucho tiempo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'e942bcf08741f7814e08e2f796d7a32126b9a6d2eb45a2e2d4b5f2a65806c954'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Lo recomiendo al 100%, es un profe muy interactivo, amable y sabe explicar muy bien. Si le pone todas las semanas en los quices semanales no tienes que hacer examen! El proyecto final es muy interesante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'c42a919ea3861050c49fce7f2deb242f1f312824679fdd2f20f9ac6ade4d6d2f'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'excelente profesor. dispuesto a ayudar a los estudiantes. da la opción de quices o trabajos adicionales para reponer las notas. hay que hacer un trabajo grande en el que se basa gran parte del curso, pero apoya un montón cada emprendimiento profe si ve esto, cásese conmigo por favor'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '51154bb196aa6cd711fd2c09908d4a085d0c7c36cc43640322018807666c5a15'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'El profesor es muy buena nota. El curso lo hace muy dinámico y entretenido. El proyecto es lo más importante del curso y es un poco difícil. Es muy buen profesor. Las asignaciones y exámenes son fáciles. Leer capítulos cada semana. 100% Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-18T00:00:00+00:00'::TIMESTAMPTZ, '8b130ae34cc4d0be7b7ec486c5516ea89dad778e7788bbc358ba5424dda9c61b'::TEXT, ARRAY[2453]::BIGINT[]),
    (63::BIGINT, 'Muy buen profe, hay que ponerle bastante con el proyecto final, pero él ayuda bastante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'a1c6001eb645404e98f1e0b1ae428d9ab088a6dba90a3a491d25d886ef271341'::TEXT, ARRAY[2442]::BIGINT[]),
    (63::BIGINT, 'Muy buen profesor, le gusta dar la clases, se emociona, es creativo y da bastantes puntos extra. Lo único que le tomara mucho tiempo es el proyecto, todo el curso se enfoca en estoy tiene que empuñarse, probablemente haya grupos que les tenga preferencia porque es casi una competencia. Muy recomend'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'cbe2fa195e6115615db364fa69bfd8aac889f179fec6d467ecf6b2e380ec85ce'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'El profesor es muy buena nota. Las clases son largas pero son muy dinámicas. Da muchos puntos extra y todos pasan. El proyecto es bastante interactivo y hay que ponerle. Deja lecturas semanales para hacer quices y son faciles. El curso es pesadillo solo por el proyecto ya que el lo lleva más allá.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'a10c22efec2850b021f1d718cc5405a08344e58e636df3ed57029de8c4744ecd'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'El profe es muy buena nota, pero es muy intenso con el proyecto y le pasa agregando cosas. Las clases pueden llegar a ser tediosas. La manera de evaluar es muy buena y ayuda a llevar la materia al día.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Da crédito extra']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '3788d4eb85b15d510df80c62f0c71475323f9a2149232ab6e69e6fcc762059a7'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Gustavo es excelente como profesor. Muy dinámico y organizado. Las clases son muy provechosas y se aprende bastante. Yo llevé Fundamentos de Mercadeo e Investigación de Mercados con él y lo recomiendo. Él está siempre dispuesto a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2019-12-22T00:00:00+00:00'::TIMESTAMPTZ, '92313cbf67616df19c6ad322605d00503b641dc951edf26dc801041b871b46b0'::TEXT, ARRAY[2453]::BIGINT[]),
    (63::BIGINT, 'Excelente profesor en investigación de mercados y fundamentos de mercadeo muy práctico en los proyectos y se aprende mucho, usa una metodología muy chiva que hace muy manejable los cursos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-12-19T00:00:00+00:00'::TIMESTAMPTZ, 'b4d535f8521b49ce204b8bdcfd05e292df6ae1997925a23971f6e1864f11ab75'::TEXT, ARRAY[2453]::BIGINT[]),
    (63::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2019-12-16T00:00:00+00:00'::TIMESTAMPTZ, '1eea24ecc3d804a12680c90ac206b8ebb6302106d6d18cbf7bcaef71c5e66db1'::TEXT, ARRAY[2453]::BIGINT[]),
    (63::BIGINT, 'Vale la pena llevar el curso con el prefe Cubiilo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2019-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'e024829a04d3313d030e5e986ae54446b0a9195e18678eff25c392836b3a682e'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Las clases no son constructivas, son aburridas, el profesor solo habla de su vida.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '672e3ec8ee5cd90e8fc7c2b9d80a278e5cf17f196e16253d28fbf9d8c3328974'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Es muy buen profe. Se aprende demasiado. Es flexible y muy buena gente. Los exámenes son muy fáciles, pero el proyecto es un poco difícil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, '5407d3bb9abd3f652d28db5913fbcc2574996e028cd7ff38819b285a16cb26ca'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-04-12T00:00:00+00:00'::TIMESTAMPTZ, '45e9fab0843deef04777a84721ddb0266516bc9be0face458a31e1051a4a1095'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'No explica nada, se pasa la clase hablando sobre las empresas en las que trabajó. Es demasiado dinámico e intenso con el proyecto'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '07fcb5200db6c4441f7161bce7169596959ffe92d5ebdc714d94d0852b256d66'::TEXT, ARRAY[1883]::BIGINT[]),
    (63::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-05-20T00:00:00+00:00'::TIMESTAMPTZ, '74bd7bc8b7b796ef8c7b25894d59e32779fc68cd1ada2f3e289ea85869d9fbb3'::TEXT, ARRAY[1784]::BIGINT[]),
    (63::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9f900596dcd8185a0855ed132195ba23d20da9ad986795fec02c6ceec26c1086'::TEXT, ARRAY[1784]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
